package com.zcshou.replay;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import android.net.Uri;import java.util.*;
/** Separate, restorable import draft; never selects or modifies an existing route. */
public final class CsvImportActivity extends Activity {
 private LinearLayout root;private TextView status;private EditText name;private CheckBox closed;private TencentMapPane map;private String raw,filename="导入路线";private RouteCsv.Document doc;private boolean dead;private int generation;
 private String example(){StringBuilder s=new StringBuilder("coordinateSystem,GCJ02\nlatitude,longitude\n");for(ReplayEngine.Point p:RouteStore.nanhu().points)s.append(p.lat).append(',').append(p.lon).append('\n');return s.toString();}
 public void onCreate(Bundle b){super.onCreate(b);MobileUi.window(this);home();if(b!=null){filename=b.getString("filename",filename);String uri=b.getString("uri");if(uri!=null)read(Uri.parse(uri),b.getString("name"),b.getBoolean("closed"));}}
 private Uri source;
 private void home(){root=MobileUi.column(this);setContentView(root);root.addView(MobileUi.text(this,"CSV 导入",24));status=MobileUi.text(this,"纬度在前，经度在后。新模板为 GCJ02；无声明的旧文件按 WGS84。最多 2 MiB、10,000 点。",16);root.addView(status);MobileUi.button(root,"选择 CSV 文件",()->{MobileUi.editable();startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),1);});MobileUi.button(root,"查看南湖示例表格",()->new AlertDialog.Builder(this).setTitle("南湖完整示例 · GCJ02").setMessage(example()).setPositiveButton("关闭",null).show());MobileUi.button(root,"保存示例 CSV",()->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("text/csv").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"南湖示例-GCJ02.csv"),2));}
 protected void onActivityResult(int q,int r,Intent d){super.onActivityResult(q,r,d);if(r!=RESULT_OK||d==null)return;if(q==2){try(java.io.OutputStream out=getContentResolver().openOutputStream(d.getData())){out.write(("\ufeff"+example()).getBytes(java.nio.charset.StandardCharsets.UTF_8));Toast.makeText(this,"模板已保存",Toast.LENGTH_SHORT).show();}catch(Exception e){status.setText("模板保存失败，请重新选择位置");}}else{source=d.getData();try{getContentResolver().takePersistableUriPermission(source,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}read(source,null,false);}}
 private void read(Uri uri,String restoredName,boolean restoredClosed){source=uri;int token=++generation;status.setText("正在检查文件…");new Thread(()->{try{String title="导入路线";try(android.database.Cursor c=getContentResolver().query(uri,null,null,null,null)){if(c!=null&&c.moveToFirst()){int i=c.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME);if(i>=0)title=c.getString(i);}}java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();try(java.io.InputStream in=getContentResolver().openInputStream(uri)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(bytes.size()+n>2097152)throw new IllegalArgumentException("文件超过 2 MiB");bytes.write(buf,0,n);}}String text=java.nio.charset.StandardCharsets.UTF_8.newDecoder().decode(java.nio.ByteBuffer.wrap(bytes.toByteArray())).toString();RouteCsv.Document parsed=RouteCsv.parseDocument(text);final String f=title;runOnUiThread(()->{if(dead||token!=generation)return;raw=text;doc=parsed;filename=f;preview(restoredName,restoredName!=null?restoredClosed:isClosed(parsed.points));});}catch(Exception e){runOnUiThread(()->{if(!dead&&token==generation)status.setText("无法导入："+(e.getMessage()==null?"请检查文件并另存为 UTF-8 CSV":e.getMessage()));});}},"csv-reader").start();}
 private boolean isClosed(List<ReplayEngine.Point> p){return p.size()>1&&p.get(0).lat==p.get(p.size()-1).lat&&p.get(0).lon==p.get(p.size()-1).lon;}
 private RouteStore.Route route(){RouteStore.Route r=new RouteStore.Route(name.getText().toString());r.coordinateSystem=doc.coordinateSystem;r.points.addAll(doc.points);if(isClosed(r.points))r.points.remove(r.points.size()-1);if(closed.isChecked())r.points.add(r.points.get(0));return r;}
 private void preview(String n,boolean c){if(map!=null)map.destroy();root.removeAllViews();root.addView(MobileUi.text(this,"检查导入路线",24));status=MobileUi.text(this,"",14);root.addView(status);name=new EditText(this);name.setSingleLine();name.setHint("路线名称");name.setText(n==null?filename.replaceFirst("(?i)\\.csv$",""):n);root.addView(name);closed=new CheckBox(this);closed.setText("闭合路线（终点连接起点）");closed.setChecked(c);root.addView(closed);map=new TencentMapPane(this,()->refresh());root.addView(map,new LinearLayout.LayoutParams(-1,MobileUi.dp(this,180)));map.coordinateSystem=doc.coordinateSystem;map.start();map.resume();ScrollView scroll=new ScrollView(this);TextView table=MobileUi.text(this,"",14);StringBuilder rows=new StringBuilder("序号     纬度                 经度\n");for(int i=0;i<doc.points.size();i++){ReplayEngine.Point p=doc.points.get(i);rows.append(i+1).append("    ").append(p.lat).append("    ").append(p.lon).append('\n');}table.setText(rows);scroll.addView(table);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));closed.setOnCheckedChangeListener((v,x)->refresh());MobileUi.button(root,"确认保存",()->{try{MobileUi.editable();if(name.getText().toString().trim().isEmpty()){name.setError("请输入路线名称");return;}RouteStore.Route r=route();try(RouteStore store=new RouteStore(this)){store.save(r);}MobileUi.detail(this,r.id);finish();}catch(Exception e){status.setText(e.getMessage());}});MobileUi.button(root,"取消导入",()->finish());refresh();}
 private void refresh(){if(doc==null||map==null)return;RouteStore.Route r=route();status.setText(filename+" · "+doc.coordinateSystem+(raw.contains("coordinateSystem,")?"":"（旧文件默认）")+String.format(java.util.Locale.CHINA," · %d 点 · %.3f km",r.points.size(),MobileUi.metres(r)/1000));map.draw(r.points,false);map.fit(r.points);}
 protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);if(source!=null)b.putString("uri",source.toString());b.putString("filename",filename);if(name!=null){b.putString("name",name.getText().toString());b.putBoolean("closed",closed.isChecked());}}
 protected void onStart(){super.onStart();if(map!=null)map.start();}protected void onResume(){super.onResume();if(map!=null)map.resume();}protected void onPause(){if(map!=null)map.pause();super.onPause();}protected void onStop(){if(map!=null)map.stop();super.onStop();}protected void onDestroy(){dead=true;generation++;if(map!=null)map.destroy();super.onDestroy();}
}
